// Create 3x3 grid
int[,] grid = new int[3, 3];

// Set values
grid[0, 0] = 1;
grid[1, 1] = 5;
grid[2, 2] = 9;

// Initialize with values
int[,] board = {
    {1, 2, 3},
    {4, 5, 6},
    {7, 8, 9}
};

// Loop through grid
for (int row = 0; row < 3; row++)
{
    for (int col = 0; col < 3; col++)
    {
        Console.WriteLine($"[{row},{col}] = {board[row, col]}");
    }
}
